"use client";

import Link from "next/link";
import Container from "./Container";
import ThemeToggle from "./ThemeToggle";
import { useState, useEffect } from "react";
import { Menu, X, Search, ChevronDown, Sparkles, LogIn } from "lucide-react";
import { assetFilters } from "@/data/mockData";

const Navbar = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [scrolled, setScrolled] = useState(false);
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
        const handleScroll = () => {
            setScrolled(window.scrollY > 50);
        };
        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    const categories = [
        { name: "Design Assets", href: "/assets?cat=design" },
        { name: "Video Templates", href: "/assets?cat=video" },
        { name: "Pinterest Keywords", href: "/keywords" },
        { name: "Curated Tools", href: "/tools" },
    ];

    if (!mounted) {
        return (
            <nav className="sticky top-0 z-50 w-full bg-background border-b border-border h-20">
                <Container className="h-full">
                    <div className="flex justify-between items-center h-full">
                        <div className="text-xl md:text-2xl font-black tracking-tighter shrink-0">ASSETNEST</div>
                        <div className="w-10 h-10" />
                    </div>
                </Container>
            </nav>
        );
    }

    return (
        <nav
            className={`sticky top-0 z-50 w-full transition-all duration-300 ${scrolled
                ? "bg-background/95 backdrop-blur-md border-b-2 border-foreground h-16 shadow-lg"
                : "bg-background border-b border-border h-20"
                }`}
        >
            <Container className="h-full">
                <div className="flex justify-between items-center h-full gap-8">
                    {/* Logo */}
                    <Link href="/" className="text-xl md:text-2xl font-black tracking-tighter shrink-0 flex items-center">
                        ASSETNEST<span className="text-[10px] font-bold align-top ml-0.5 opacity-50">TM</span>
                    </Link>

                    {/* Nav Search Bar (Visible on scroll) */}
                    <div className="hidden lg:flex items-center flex-grow max-w-lg">
                        <div className={`flex items-center bg-zinc-100 dark:bg-zinc-900 border border-border px-4 py-2 w-full transition-all duration-500 ${scrolled ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-2 pointer-events-none'}`}>
                            <Search size={16} className="text-secondary mr-3" />
                            <input
                                type="text"
                                placeholder="Search assets..."
                                className="bg-transparent text-sm w-full focus:outline-none placeholder:text-secondary/50 font-medium"
                            />
                        </div>
                    </div>

                    {/* Desktop Actions */}
                    <div className="hidden md:flex items-center space-x-6">
                        <Link
                            href="/premium"
                            className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest bg-foreground text-background px-6 py-2.5 hover:opacity-90 active:scale-95 transition-all"
                        >
                            GET PRO
                        </Link>

                        <div className="flex items-center gap-6 border-l border-border pl-8">
                            <ThemeToggle />
                            <button className="text-[10px] font-black uppercase tracking-widest flex items-center gap-2 hover:opacity-70 transition-opacity">
                                SIGN IN
                            </button>
                        </div>

                        <div className="h-8 w-px bg-border/50 mx-2"></div>

                        <button
                            onClick={() => setIsOpen(!isOpen)}
                            className="flex items-center gap-3 group pl-2"
                        >
                            <span className="text-[10px] font-black uppercase tracking-[0.3em]">Menu</span>
                            <div className="flex flex-col gap-1 items-end">
                                <span className={`h-0.5 bg-foreground transition-all duration-300 ${isOpen ? 'w-6 -rotate-45 -translate-y-[-6px]' : 'w-6'}`}></span>
                                <span className={`h-0.5 bg-foreground transition-all duration-300 ${isOpen ? 'opacity-0' : 'w-4'}`}></span>
                                <span className={`h-0.5 bg-foreground transition-all duration-300 ${isOpen ? 'w-6 rotate-45 translate-y-[-6px]' : 'w-5'}`}></span>
                            </div>
                        </button>
                    </div>

                    {/* Mobile Toggle */}
                    <div className="md:hidden flex items-center space-x-4">
                        <ThemeToggle />
                        <button
                            onClick={() => setIsOpen(!isOpen)}
                            aria-label="Toggle menu"
                            className="p-2"
                        >
                            {isOpen ? <X size={24} /> : <Menu size={24} />}
                        </button>
                    </div>
                </div>

                {/* Unified Menu Overlay (Desktop and Mobile) */}
                {isOpen && (
                    <div className="fixed inset-0 top-[64px] md:top-[80px] bg-background/98 backdrop-blur-xl z-[100] animate-in fade-in slide-in-from-top duration-500 overflow-y-auto">
                        <Container className="py-20">
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-20">
                                {/* Section 1: Categories */}
                                <div className="space-y-10">
                                    <p className="text-[10px] font-black tracking-[0.5em] text-secondary uppercase border-b border-border pb-4">Asset Categories</p>
                                    <div className="flex flex-col space-y-2">
                                        {assetFilters.map((item) => (
                                            <Link
                                                key={item}
                                                href={`/assets?filter=${item.toLowerCase().replace(' ', '-')}`}
                                                className="text-lg md:text-xl font-black uppercase tracking-widest hover:bg-foreground hover:text-background px-6 py-3 transition-all border-2 border-transparent hover:border-foreground"
                                                onClick={() => setIsOpen(false)}
                                            >
                                                {item}
                                            </Link>
                                        ))}
                                    </div>
                                </div>

                                {/* Section 2: Resources */}
                                <div className="space-y-10">
                                    <p className="text-[10px] font-black tracking-[0.5em] text-secondary uppercase border-b border-border pb-4">Strategic Tools</p>
                                    <div className="flex flex-col space-y-6">
                                        {categories.map((link) => (
                                            <Link
                                                key={link.name}
                                                href={link.href}
                                                className="text-2xl md:text-3xl font-black uppercase tracking-tight hover:text-secondary transition-all flex items-center gap-4 group"
                                                onClick={() => setIsOpen(false)}
                                            >
                                                <div className="w-0 h-0.5 bg-foreground group-hover:w-8 transition-all duration-300"></div>
                                                {link.name}
                                            </Link>
                                        ))}
                                    </div>
                                </div>

                                {/* Section 3: Pro & Auth */}
                                <div className="space-y-10">
                                    <p className="text-[10px] font-black tracking-[0.5em] text-secondary uppercase border-b border-border pb-4">Premium Access</p>
                                    <div className="bg-zinc-50 dark:bg-zinc-950 p-10 border-2 border-foreground shadow-[16px_16px_0px_0px_rgba(0,0,0,1)] dark:shadow-[16px_16px_0px_0px_rgba(255,255,255,1)]">
                                        <h3 className="text-2xl font-black uppercase mb-4">Level Up Your Content</h3>
                                        <p className="text-secondary font-medium mb-8 leading-relaxed">Join 50,000+ creators getting weekly assets and insights.</p>
                                        <Link
                                            href="/premium"
                                            className="block w-full bg-foreground text-background py-5 font-black uppercase tracking-widest text-center hover:opacity-90 transition-opacity"
                                            onClick={() => setIsOpen(false)}
                                        >
                                            Upgrade to Pro
                                        </Link>
                                        <button className="block w-full border-2 border-foreground mt-4 py-5 font-black uppercase tracking-widest text-center hover:bg-foreground hover:text-background transition-all">
                                            Partner Login
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </Container>
                    </div>
                )}
            </Container>
        </nav>
    );
};

export default Navbar;
